-- 세트 230: Deployment 롤아웃과 복구: 이미지 업데이트, 이력 읽기, 잘못된 이미지 되돌리기, 재시작
-- 명세: docs/specs/spec_k8s_rollout_recovery_set.md. 정답·해설은 서버만 안다. 실습 문제의 grade_cmd 는 checks 의 조건을 && 로 이은 것과 같다.
INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs) VALUES
  (230, 1, 'Deployment 만들기', 'Deployment `web` 을 만드세요. 이미지는 `nginx:1.25`, 복제본(Pod)은 2개입니다. 만든 뒤 Pod 가 모두 준비될 때까지 확인하세요.', '`kubectl create deployment 이름 --image=이미지` 에 복제본 수를 정하는 옵션을 붙입니다. 준비 확인은 `kubectl get pods` 의 READY 칸을 보세요.', 'kubectl create deployment web --image=nginx:1.25 --replicas=2 -n $NS
kubectl rollout status deploy/web -n $NS
kubectl get pods -n $NS

# create deployment 는 Deployment 와 그 아래 ReplicaSet, Pod 까지 한 번에 만든다
# READY 가 1/1 인 Pod 가 2개면 준비 끝', '["sh", "-c", "rm -f /tmp/*.txt; kubectl delete deploy web -n $NS --now --cascade=foreground --wait=true --timeout=60s >/dev/null 2>&1; true"]', '["sh", "-c", "( [ \\"$(kubectl get deploy web -n $NS -o jsonpath=''{.spec.template.spec.containers[0].image}'' 2>/dev/null)\\" = nginx:1.25 ] ) && ( i=0; while [ $i -lt 30 ]; do if [ \\"$(kubectl get deploy web -n $NS -o jsonpath=''{.status.readyReplicas}/{.status.updatedReplicas}/{.status.replicas}'' 2>/dev/null)\\" = 2/2/2 ]; then exit 0; fi; sleep 1; i=$((i+1)); done; exit 1 )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "이미지가 nginx:1.25 이다", "cmd": ["sh", "-c", "[ \\"$(kubectl get deploy web -n $NS -o jsonpath=''{.spec.template.spec.containers[0].image}'' 2>/dev/null)\\" = nginx:1.25 ]"]}, {"label": "Pod 2개가 모두 준비됐다", "cmd": ["sh", "-c", "i=0; while [ $i -lt 30 ]; do if [ \\"$(kubectl get deploy web -n $NS -o jsonpath=''{.status.readyReplicas}/{.status.updatedReplicas}/{.status.replicas}'' 2>/dev/null)\\" = 2/2/2 ]; then exit 0; fi; sleep 1; i=$((i+1)); done; exit 1"]}]', '[{"title": "Deployment", "url": "https://kubernetes.io/docs/concepts/workloads/controllers/deployment/"}, {"title": "kubectl rollout", "url": "https://kubernetes.io/docs/reference/kubectl/generated/kubectl_rollout/"}, {"title": "Pod 디버깅", "url": "https://kubernetes.io/docs/tasks/debug/debug-application/debug-pods/"}]'),
  (230, 2, '복제본 수 늘리기', 'Deployment `web` 의 Pod 가 지금 2개인데 요청이 늘었습니다. **복제본을 4개로** 늘리고 Pod 4개가 모두 준비될 때까지 확인하세요.', '`kubectl scale` 에 대상(`deploy/web`)과 `--replicas=` 옵션을 씁니다.', 'kubectl scale deploy/web --replicas=4 -n $NS
kubectl get pods -n $NS

# scale 은 이미지를 건드리지 않고 Pod 개수만 바꾼다', '["sh", "-c", "rm -f /tmp/*.txt; kubectl delete deploy web -n $NS --now --cascade=foreground --wait=true --timeout=60s >/dev/null 2>&1; kubectl create deployment web --image=nginx:1.25 --replicas=2 -n $NS >/dev/null 2>&1; kubectl rollout status deploy/web -n $NS --timeout=120s >/dev/null 2>&1; true"]', '["sh", "-c", "( [ \\"$(kubectl get deploy web -n $NS -o jsonpath=''{.spec.replicas}'' 2>/dev/null)\\" = 4 ] ) && ( i=0; while [ $i -lt 30 ]; do if [ \\"$(kubectl get deploy web -n $NS -o jsonpath=''{.status.readyReplicas}/{.status.updatedReplicas}/{.status.replicas}'' 2>/dev/null)\\" = 4/4/4 ]; then exit 0; fi; sleep 1; i=$((i+1)); done; exit 1 ) && ( [ \\"$(kubectl get deploy web -n $NS -o jsonpath=''{.spec.template.spec.containers[0].image}'' 2>/dev/null)\\" = nginx:1.25 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "복제본 목표가 4이다", "cmd": ["sh", "-c", "[ \\"$(kubectl get deploy web -n $NS -o jsonpath=''{.spec.replicas}'' 2>/dev/null)\\" = 4 ]"]}, {"label": "Pod 4개가 모두 준비됐다", "cmd": ["sh", "-c", "i=0; while [ $i -lt 30 ]; do if [ \\"$(kubectl get deploy web -n $NS -o jsonpath=''{.status.readyReplicas}/{.status.updatedReplicas}/{.status.replicas}'' 2>/dev/null)\\" = 4/4/4 ]; then exit 0; fi; sleep 1; i=$((i+1)); done; exit 1"]}, {"label": "이미지는 그대로 nginx:1.25 이다", "cmd": ["sh", "-c", "[ \\"$(kubectl get deploy web -n $NS -o jsonpath=''{.spec.template.spec.containers[0].image}'' 2>/dev/null)\\" = nginx:1.25 ]"]}]', '[{"title": "Deployment", "url": "https://kubernetes.io/docs/concepts/workloads/controllers/deployment/"}, {"title": "kubectl rollout", "url": "https://kubernetes.io/docs/reference/kubectl/generated/kubectl_rollout/"}, {"title": "Pod 디버깅", "url": "https://kubernetes.io/docs/tasks/debug/debug-application/debug-pods/"}]'),
  (230, 3, 'set image 로 이미지 바꾸기', 'Deployment `web` 이 `nginx:1.25` 로 돌고 있습니다. 이미지를 **`nginx:1.27-alpine`** 으로 바꾸세요. 새 Pod 로 하나씩 교체(롤링 업데이트)되고, 끝나면 Pod 2개가 모두 새 이미지로 준비되어야 합니다.', '`kubectl set image deploy/web 컨테이너이름=이미지` 형식입니다. 컨테이너 이름은 `kubectl get deploy web -o wide` 의 CONTAINERS 칸에 보여요.', 'kubectl get deploy web -o wide -n $NS
kubectl set image deploy/web nginx=nginx:1.27-alpine -n $NS
kubectl rollout status deploy/web -n $NS

# set image 는 Pod 템플릿을 바꾸므로 새 ReplicaSet 이 생기고 Pod 가 하나씩 교체된다
# rollout status 는 교체가 끝나면 successfully rolled out 을 출력하고 돌아온다', '["sh", "-c", "rm -f /tmp/*.txt; kubectl delete deploy web -n $NS --now --cascade=foreground --wait=true --timeout=60s >/dev/null 2>&1; kubectl create deployment web --image=nginx:1.25 --replicas=2 -n $NS >/dev/null 2>&1; kubectl rollout status deploy/web -n $NS --timeout=120s >/dev/null 2>&1; true"]', '["sh", "-c", "( [ \\"$(kubectl get deploy web -n $NS -o jsonpath=''{.spec.template.spec.containers[0].image}'' 2>/dev/null)\\" = nginx:1.27-alpine ] ) && ( i=0; while [ $i -lt 40 ]; do if [ \\"$(kubectl get deploy web -n $NS -o jsonpath=''{.status.readyReplicas}/{.status.updatedReplicas}/{.status.replicas}'' 2>/dev/null)\\" = 2/2/2 ]; then exit 0; fi; sleep 1; i=$((i+1)); done; exit 1 )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "이미지가 nginx:1.27-alpine 이다", "cmd": ["sh", "-c", "[ \\"$(kubectl get deploy web -n $NS -o jsonpath=''{.spec.template.spec.containers[0].image}'' 2>/dev/null)\\" = nginx:1.27-alpine ]"]}, {"label": "Pod 2개가 모두 새 이미지로 준비됐다", "cmd": ["sh", "-c", "i=0; while [ $i -lt 40 ]; do if [ \\"$(kubectl get deploy web -n $NS -o jsonpath=''{.status.readyReplicas}/{.status.updatedReplicas}/{.status.replicas}'' 2>/dev/null)\\" = 2/2/2 ]; then exit 0; fi; sleep 1; i=$((i+1)); done; exit 1"]}]', '[{"title": "Deployment", "url": "https://kubernetes.io/docs/concepts/workloads/controllers/deployment/"}, {"title": "kubectl rollout", "url": "https://kubernetes.io/docs/reference/kubectl/generated/kubectl_rollout/"}, {"title": "Pod 디버깅", "url": "https://kubernetes.io/docs/tasks/debug/debug-application/debug-pods/"}]'),
  (230, 4, 'rollout history 로 REVISION 보기', 'Deployment `web` 은 이미지를 한 번 바꿨습니다. **업데이트 이력**을 `/tmp/history.txt` 에 저장하세요. `REVISION` 번호가 몇 번까지 있는지 확인해 보세요.', '`kubectl rollout history deploy/web` 의 결과를 `>` 로 파일에 저장하고 `cat` 으로 읽어 보세요.', 'kubectl rollout history deploy/web -n $NS > /tmp/history.txt
cat /tmp/history.txt

# REVISION 1 은 처음 만든 버전, 2 는 이미지를 바꾼 뒤의 버전이다
# CHANGE-CAUSE 가 <none> 이면 아무도 사유를 적지 않은 것이다', '["sh", "-c", "rm -f /tmp/*.txt; kubectl delete deploy web -n $NS --now --cascade=foreground --wait=true --timeout=60s >/dev/null 2>&1; kubectl create deployment web --image=nginx:1.24 --replicas=2 -n $NS >/dev/null 2>&1; kubectl rollout status deploy/web -n $NS --timeout=120s >/dev/null 2>&1; kubectl set image deploy/web nginx=nginx:1.25 -n $NS >/dev/null 2>&1; kubectl rollout status deploy/web -n $NS --timeout=120s >/dev/null 2>&1; true"]', '["sh", "-c", "( grep -q \\"^REVISION\\" /tmp/history.txt ) && ( grep -Eq \\"^1 \\" /tmp/history.txt && grep -Eq \\"^2 \\" /tmp/history.txt ) && ( ! grep -Eq \\"^3 \\" /tmp/history.txt )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "REVISION 머리글이 있다", "cmd": ["sh", "-c", "grep -q \\"^REVISION\\" /tmp/history.txt"]}, {"label": "1번과 2번 REVISION 이 있다", "cmd": ["sh", "-c", "grep -Eq \\"^1 \\" /tmp/history.txt && grep -Eq \\"^2 \\" /tmp/history.txt"]}, {"label": "3번은 없다", "cmd": ["sh", "-c", "! grep -Eq \\"^3 \\" /tmp/history.txt"]}]', '[{"title": "Deployment", "url": "https://kubernetes.io/docs/concepts/workloads/controllers/deployment/"}, {"title": "kubectl rollout", "url": "https://kubernetes.io/docs/reference/kubectl/generated/kubectl_rollout/"}, {"title": "Pod 디버깅", "url": "https://kubernetes.io/docs/tasks/debug/debug-application/debug-pods/"}]'),
  (230, 5, 'get pods 로 이미지 오류 알아채기', '누군가 `web` 의 이미지를 바꿨는데 업데이트가 끝나지 않는 것 같습니다. **Pod 목록**을 `/tmp/pods.txt` 에 저장하고 STATUS 칸에 어떤 문제가 보이는지 확인하세요.', '`kubectl get pods` 의 결과를 파일에 저장하고 `cat` 으로 읽어 보세요. 정상 Pod 와 다른 STATUS 를 가진 줄을 찾으면 됩니다.', 'kubectl get pods -n $NS > /tmp/pods.txt
cat /tmp/pods.txt

# 새 Pod 의 STATUS 가 ErrImagePull 또는 ImagePullBackOff 이다 (이미지를 받아 오지 못하는 중)
# 이전 Pod 는 아직 Running 이라서 서비스가 바로 끊기지는 않는다', '["sh", "-c", "rm -f /tmp/*.txt; kubectl delete deploy web -n $NS --now --cascade=foreground --wait=true --timeout=60s >/dev/null 2>&1; kubectl create deployment web --image=nginx:1.25 --replicas=2 -n $NS >/dev/null 2>&1; kubectl rollout status deploy/web -n $NS --timeout=120s >/dev/null 2>&1; kubectl set image deploy/web nginx=nginx:1.27-alpne -n $NS >/dev/null 2>&1; i=0; while [ $i -lt 60 ]; do kubectl get pods -n $NS -o jsonpath=''{.items[*].status.containerStatuses[*].state.waiting.reason}'' 2>/dev/null | grep -Eq ''ErrImagePull|ImagePullBackOff'' && break; sleep 1; i=$((i+1)); done; true"]', '["sh", "-c", "( grep -q \\"^NAME\\" /tmp/pods.txt ) && ( grep -Eq \\"^web-[a-z0-9]+-[a-z0-9]+ .*(ErrImagePull|ImagePullBackOff)\\" /tmp/pods.txt )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "Pod 목록이 저장됐다", "cmd": ["sh", "-c", "grep -q \\"^NAME\\" /tmp/pods.txt"]}, {"label": "이미지 오류 상태가 보인다", "cmd": ["sh", "-c", "grep -Eq \\"^web-[a-z0-9]+-[a-z0-9]+ .*(ErrImagePull|ImagePullBackOff)\\" /tmp/pods.txt"]}]', '[{"title": "Deployment", "url": "https://kubernetes.io/docs/concepts/workloads/controllers/deployment/"}, {"title": "kubectl rollout", "url": "https://kubernetes.io/docs/reference/kubectl/generated/kubectl_rollout/"}, {"title": "Pod 디버깅", "url": "https://kubernetes.io/docs/tasks/debug/debug-application/debug-pods/"}]'),
  (230, 6, '이미지를 못 받는 이유는 어디서 볼까', 'Pod 의 STATUS 가 `ImagePullBackOff` 입니다. 이미지를 **왜 못 받는지** 자세한 이유(`Failed to pull image ...`)를 볼 수 있는 곳은 어디일까요?', '`describe` 의 맨 아래 Events 칸은 Pod 에 일어난 일을 시간순으로 보여 줘요.', NULL, NULL, '[]', 'choice', '["`kubectl rollout history deploy/web`", "`kubectl describe pod 이름` 맨 아래 Events", "`kubectl logs deploy/web`", "`kubectl get rs` 의 DESIRED 칸"]', 1, '이미지 당기기에 실패한 이유는 Pod 의 Events 에 남습니다. `describe pod` 맨 아래에서 `Failed to pull image "..."` 와 함께 이미지가 없다는 메시지를 볼 수 있어요. `rollout history` 는 버전 번호와 사유만 보여 주고, 컨테이너가 시작되지 못했으니 `logs` 에는 읽을 로그가 없습니다. `get rs` 는 개수만 보여 줍니다.', NULL, NULL, NULL, NULL),
  (230, 7, 'rollout undo 로 이전 버전으로 되돌리기', '`web` 의 이미지를 잘못 적은 탓에 새 Pod 가 `ImagePullBackOff` 로 막혀 있습니다. **직전의 정상 버전으로 되돌려서** Pod 2개가 모두 정상 이미지로 준비되게 하세요.', '`kubectl rollout` 아래에 "되돌리기"를 뜻하는 하위 명령이 있어요. 끝난 뒤 `kubectl get pods` 로 확인하세요.', 'kubectl rollout undo deploy/web -n $NS
kubectl rollout status deploy/web -n $NS
kubectl get pods -n $NS

# undo 는 바로 앞 REVISION 의 Pod 템플릿으로 되돌린다
# 막혀 있던 새 Pod 는 사라지고 이전 Pod 가 정상 개수로 복구된다', '["sh", "-c", "rm -f /tmp/*.txt; kubectl delete deploy web -n $NS --now --cascade=foreground --wait=true --timeout=60s >/dev/null 2>&1; kubectl create deployment web --image=nginx:1.25 --replicas=2 -n $NS >/dev/null 2>&1; kubectl rollout status deploy/web -n $NS --timeout=120s >/dev/null 2>&1; kubectl set image deploy/web nginx=nginx:1.27-alpne -n $NS >/dev/null 2>&1; i=0; while [ $i -lt 60 ]; do kubectl get pods -n $NS -o jsonpath=''{.items[*].status.containerStatuses[*].state.waiting.reason}'' 2>/dev/null | grep -Eq ''ErrImagePull|ImagePullBackOff'' && break; sleep 1; i=$((i+1)); done; true"]', '["sh", "-c", "( [ \\"$(kubectl get deploy web -n $NS -o jsonpath=''{.spec.template.spec.containers[0].image}'' 2>/dev/null)\\" = nginx:1.25 ] ) && ( i=0; while [ $i -lt 40 ]; do if [ \\"$(kubectl get deploy web -n $NS -o jsonpath=''{.status.readyReplicas}/{.status.updatedReplicas}/{.status.replicas}'' 2>/dev/null)\\" = 2/2/2 ]; then exit 0; fi; sleep 1; i=$((i+1)); done; exit 1 )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "이미지가 nginx:1.25 로 돌아왔다", "cmd": ["sh", "-c", "[ \\"$(kubectl get deploy web -n $NS -o jsonpath=''{.spec.template.spec.containers[0].image}'' 2>/dev/null)\\" = nginx:1.25 ]"]}, {"label": "Pod 2개가 모두 준비됐다", "cmd": ["sh", "-c", "i=0; while [ $i -lt 40 ]; do if [ \\"$(kubectl get deploy web -n $NS -o jsonpath=''{.status.readyReplicas}/{.status.updatedReplicas}/{.status.replicas}'' 2>/dev/null)\\" = 2/2/2 ]; then exit 0; fi; sleep 1; i=$((i+1)); done; exit 1"]}]', '[{"title": "Deployment", "url": "https://kubernetes.io/docs/concepts/workloads/controllers/deployment/"}, {"title": "kubectl rollout", "url": "https://kubernetes.io/docs/reference/kubectl/generated/kubectl_rollout/"}, {"title": "Pod 디버깅", "url": "https://kubernetes.io/docs/tasks/debug/debug-application/debug-pods/"}]'),
  (230, 8, '변경 사유를 적는 annotation', '`rollout history` 의 `CHANGE-CAUSE` 칸은 Deployment 의 annotation 으로 채웁니다. 빈칸에 들어갈 annotation 이름을 고르세요.', '`rollout history` 표의 맨 오른쪽 열 이름을 소문자로 바꿔 보세요.', NULL, NULL, '[]', 'fill', '["change-cause", "cause", "reason", "revision"]', NULL, '`kubernetes.io/change-cause` annotation 의 값이 `rollout history` 의 CHANGE-CAUSE 칸에 나타납니다. 이 annotation 은 Deployment 에 붙이면 현재 REVISION 에 반영됩니다.', '[0]', 'kubectl annotate deploy/web kubernetes.io/{0}="upgrade to 1.27"', NULL, NULL),
  (230, 9, 'annotate 로 CHANGE-CAUSE 채우기', 'Deployment `web` 의 이미지를 막 `nginx:1.27-alpine` 으로 올렸습니다. 이력의 REVISION 2 줄에 **`upgrade to 1.27`** 이라는 사유가 보이게 하세요.', '`kubectl annotate deploy/web 키=값` 형식입니다. 키는 `kubernetes.io/` 로 시작해요. 끝난 뒤 `rollout history` 를 다시 보세요.', 'kubectl rollout history deploy/web -n $NS
kubectl annotate deploy/web kubernetes.io/change-cause="upgrade to 1.27" -n $NS
kubectl rollout history deploy/web -n $NS

# annotate 전에는 CHANGE-CAUSE 가 <none>, 후에는 REVISION 2 줄에 사유가 보인다
# 값에 공백이 있으면 따옴표로 감싼다', '["sh", "-c", "rm -f /tmp/*.txt; kubectl delete deploy web -n $NS --now --cascade=foreground --wait=true --timeout=60s >/dev/null 2>&1; kubectl create deployment web --image=nginx:1.25 --replicas=2 -n $NS >/dev/null 2>&1; kubectl rollout status deploy/web -n $NS --timeout=120s >/dev/null 2>&1; kubectl set image deploy/web nginx=nginx:1.27-alpine -n $NS >/dev/null 2>&1; kubectl rollout status deploy/web -n $NS --timeout=120s >/dev/null 2>&1; true"]', '["sh", "-c", "( [ \\"$(kubectl get deploy web -n $NS -o jsonpath=''{.metadata.annotations.kubernetes\\\\.io/change-cause}'' 2>/dev/null)\\" = \\"upgrade to 1.27\\" ] ) && ( i=0; while [ $i -lt 15 ]; do if kubectl rollout history deploy/web -n $NS 2>/dev/null | grep -Eq \\"^2 +upgrade to 1.27\\"; then exit 0; fi; sleep 1; i=$((i+1)); done; exit 1 )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "change-cause 가 upgrade to 1.27 이다", "cmd": ["sh", "-c", "[ \\"$(kubectl get deploy web -n $NS -o jsonpath=''{.metadata.annotations.kubernetes\\\\.io/change-cause}'' 2>/dev/null)\\" = \\"upgrade to 1.27\\" ]"]}, {"label": "REVISION 2 줄에 사유가 보인다", "cmd": ["sh", "-c", "i=0; while [ $i -lt 15 ]; do if kubectl rollout history deploy/web -n $NS 2>/dev/null | grep -Eq \\"^2 +upgrade to 1.27\\"; then exit 0; fi; sleep 1; i=$((i+1)); done; exit 1"]}]', '[{"title": "Deployment", "url": "https://kubernetes.io/docs/concepts/workloads/controllers/deployment/"}, {"title": "kubectl rollout", "url": "https://kubernetes.io/docs/reference/kubectl/generated/kubectl_rollout/"}, {"title": "Pod 디버깅", "url": "https://kubernetes.io/docs/tasks/debug/debug-application/debug-pods/"}]'),
  (230, 10, 'rollout restart 로 Pod 새로 띄우기', 'Deployment `web` 의 이미지는 그대로 두고, **Pod 만 새것으로 하나씩 다시 띄우세요.** (설정을 바꾼 뒤 새로 읽게 하고 싶을 때 쓰는 방법이에요.) 끝나면 Pod 2개가 모두 준비되어야 합니다.', '`kubectl rollout` 아래의 "다시 시작"을 뜻하는 하위 명령입니다. 이미지는 바꾸지 않아요.', 'kubectl rollout restart deploy/web -n $NS
kubectl rollout status deploy/web -n $NS
kubectl rollout history deploy/web -n $NS

# restart 는 Pod 템플릿에 재시작 시각을 적어 새 ReplicaSet 을 만든다 (이미지는 그대로)
# 그래서 REVISION 이 하나 늘어 2 가 된다', '["sh", "-c", "rm -f /tmp/*.txt; kubectl delete deploy web -n $NS --now --cascade=foreground --wait=true --timeout=60s >/dev/null 2>&1; kubectl create deployment web --image=nginx:1.25 --replicas=2 -n $NS >/dev/null 2>&1; kubectl rollout status deploy/web -n $NS --timeout=120s >/dev/null 2>&1; true"]', '["sh", "-c", "( i=0; while [ $i -lt 20 ]; do if [ \\"$(kubectl get deploy web -n $NS -o jsonpath=''{.metadata.annotations.deployment\\\\.kubernetes\\\\.io/revision}'' 2>/dev/null)\\" = 2 ]; then exit 0; fi; sleep 1; i=$((i+1)); done; exit 1 ) && ( [ \\"$(kubectl get deploy web -n $NS -o jsonpath=''{.spec.template.spec.containers[0].image}'' 2>/dev/null)\\" = nginx:1.25 ] ) && ( i=0; while [ $i -lt 40 ]; do if [ \\"$(kubectl get deploy web -n $NS -o jsonpath=''{.status.readyReplicas}/{.status.updatedReplicas}/{.status.replicas}'' 2>/dev/null)\\" = 2/2/2 ]; then exit 0; fi; sleep 1; i=$((i+1)); done; exit 1 )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "REVISION 이 2 이다", "cmd": ["sh", "-c", "i=0; while [ $i -lt 20 ]; do if [ \\"$(kubectl get deploy web -n $NS -o jsonpath=''{.metadata.annotations.deployment\\\\.kubernetes\\\\.io/revision}'' 2>/dev/null)\\" = 2 ]; then exit 0; fi; sleep 1; i=$((i+1)); done; exit 1"]}, {"label": "이미지는 그대로 nginx:1.25 이다", "cmd": ["sh", "-c", "[ \\"$(kubectl get deploy web -n $NS -o jsonpath=''{.spec.template.spec.containers[0].image}'' 2>/dev/null)\\" = nginx:1.25 ]"]}, {"label": "Pod 2개가 모두 준비됐다", "cmd": ["sh", "-c", "i=0; while [ $i -lt 40 ]; do if [ \\"$(kubectl get deploy web -n $NS -o jsonpath=''{.status.readyReplicas}/{.status.updatedReplicas}/{.status.replicas}'' 2>/dev/null)\\" = 2/2/2 ]; then exit 0; fi; sleep 1; i=$((i+1)); done; exit 1"]}]', '[{"title": "Deployment", "url": "https://kubernetes.io/docs/concepts/workloads/controllers/deployment/"}, {"title": "kubectl rollout", "url": "https://kubernetes.io/docs/reference/kubectl/generated/kubectl_rollout/"}, {"title": "Pod 디버깅", "url": "https://kubernetes.io/docs/tasks/debug/debug-application/debug-pods/"}]'),
  (230, 11, 'rollout undo --to-revision 으로 옛 버전 골라 가기', 'Deployment `web` 은 이미지를 두 번 바꿔 지금 REVISION 3(`nginx:1.27-alpine`)입니다. **가장 처음 버전(REVISION 1)** 으로 되돌리세요. 먼저 REVISION 1 의 이미지가 무엇인지 이력에서 확인하고, 되돌린 뒤 Pod 2개가 준비되어야 합니다.', '`kubectl rollout history deploy/web --revision=번호` 로 그 버전의 이미지를 볼 수 있어요. 되돌릴 때는 `rollout undo` 에 `--to-revision=번호` 를 붙입니다.', 'kubectl rollout history deploy/web -n $NS
kubectl rollout history deploy/web --revision=1 -n $NS
kubectl rollout undo deploy/web --to-revision=1 -n $NS
kubectl rollout status deploy/web -n $NS
kubectl rollout history deploy/web -n $NS

# --to-revision 없이 undo 하면 바로 앞(REVISION 2)으로만 간다
# 되돌린 버전은 옛 번호를 버리고 새 번호(4)로 이력의 맨 끝에 올라간다', '["sh", "-c", "rm -f /tmp/*.txt; kubectl delete deploy web -n $NS --now --cascade=foreground --wait=true --timeout=60s >/dev/null 2>&1; kubectl create deployment web --image=nginx:1.24 --replicas=2 -n $NS >/dev/null 2>&1; kubectl rollout status deploy/web -n $NS --timeout=120s >/dev/null 2>&1; kubectl set image deploy/web nginx=nginx:1.25 -n $NS >/dev/null 2>&1; kubectl rollout status deploy/web -n $NS --timeout=120s >/dev/null 2>&1; kubectl set image deploy/web nginx=nginx:1.27-alpine -n $NS >/dev/null 2>&1; kubectl rollout status deploy/web -n $NS --timeout=120s >/dev/null 2>&1; true"]', '["sh", "-c", "( [ \\"$(kubectl get deploy web -n $NS -o jsonpath=''{.spec.template.spec.containers[0].image}'' 2>/dev/null)\\" = nginx:1.24 ] ) && ( i=0; while [ $i -lt 40 ]; do if [ \\"$(kubectl get deploy web -n $NS -o jsonpath=''{.status.readyReplicas}/{.status.updatedReplicas}/{.status.replicas}'' 2>/dev/null)\\" = 2/2/2 ]; then exit 0; fi; sleep 1; i=$((i+1)); done; exit 1 ) && ( [ \\"$(kubectl get deploy web -n $NS -o jsonpath=''{.metadata.annotations.deployment\\\\.kubernetes\\\\.io/revision}'' 2>/dev/null)\\" = 4 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "이미지가 nginx:1.24 로 돌아왔다", "cmd": ["sh", "-c", "[ \\"$(kubectl get deploy web -n $NS -o jsonpath=''{.spec.template.spec.containers[0].image}'' 2>/dev/null)\\" = nginx:1.24 ]"]}, {"label": "Pod 2개가 모두 준비됐다", "cmd": ["sh", "-c", "i=0; while [ $i -lt 40 ]; do if [ \\"$(kubectl get deploy web -n $NS -o jsonpath=''{.status.readyReplicas}/{.status.updatedReplicas}/{.status.replicas}'' 2>/dev/null)\\" = 2/2/2 ]; then exit 0; fi; sleep 1; i=$((i+1)); done; exit 1"]}, {"label": "REVISION 이 4 이다 (옛 버전이 새 번호로 올라감)", "cmd": ["sh", "-c", "[ \\"$(kubectl get deploy web -n $NS -o jsonpath=''{.metadata.annotations.deployment\\\\.kubernetes\\\\.io/revision}'' 2>/dev/null)\\" = 4 ]"]}]', '[{"title": "Deployment", "url": "https://kubernetes.io/docs/concepts/workloads/controllers/deployment/"}, {"title": "kubectl rollout", "url": "https://kubernetes.io/docs/reference/kubectl/generated/kubectl_rollout/"}, {"title": "Pod 디버깅", "url": "https://kubernetes.io/docs/tasks/debug/debug-application/debug-pods/"}]'),
  (230, 12, '이미지 업데이트가 막혔을 때 복구하는 순서', '새 이미지로 업데이트했는데 막혀서 복구하는 순서입니다. 순서에 맞게 놓아 보세요.', '먼저 바꾸고 기다려 보고, 증상을 보고 이유를 찾은 다음, 되돌리고 다시 확인합니다.', NULL, NULL, '[]', 'order', '["`kubectl describe pod 이름` 의 Events 에서 이미지를 못 받는 이유를 확인한다", "`kubectl set image deploy/web nginx=새이미지` 로 이미지를 바꾼다", "`kubectl rollout status deploy/web` 로 되돌린 뒤 정상으로 끝났는지 확인한다", "`kubectl get pods` 에서 새 Pod 의 STATUS 가 ErrImagePull 인지 본다", "`kubectl rollout undo deploy/web` 으로 직전 버전으로 되돌린다", "`kubectl rollout status deploy/web` 로 끝나는지 기다려 본다"]', NULL, '바꾼 뒤 `rollout status` 가 끝나지 않으면 이상 신호입니다. `get pods` 로 증상(ErrImagePull)을 보고, `describe pod` 의 Events 로 이유를 확인합니다. 이유를 알았으면 `rollout undo` 로 직전 버전으로 돌리고, 마지막으로 `rollout status` 와 같은 명령으로 정말 복구됐는지 확인합니다.', '[1, 5, 3, 0, 4, 2]', NULL, NULL, NULL);
